// Generated by GPT-6.2 Astra
`timescale 1ns/1ps

module npu_mac_tb;
    logic clk = 1'b0;
    logic rst_n = 1'b0;
    logic clear = 1'b0;
    logic in_valid = 1'b0;
    logic in_last = 1'b0;
    logic signed [7:0] a = 8'sd0;
    logic signed [7:0] b = 8'sd0;

    logic signed [31:0] result;
    logic result_valid;

    longint signed reference_sum = 0;
    logic signed [31:0] expected_result = 32'sd0;
    logic expected_valid = 1'b0;
    logic [31:0] random_state = 32'h2642_1234;
    integer checks = 0;
    integer cases = 0;
    integer random_a;
    integer random_b;
    integer group_length;
    string case_name;

    always #5 clk = ~clk;

    npu_mac u_npu_mac(
        .clk          (clk         ),
        .rst_n        (rst_n       ),
        .clear        (clear       ),
        .in_valid     (in_valid    ),
        .in_last      (in_last     ),
        .a            (a           ),
        .b            (b           ),
        .result       (result      ),
        .result_valid (result_valid)
    );

    task automatic begin_case
        (input string name);
        case_name = name;
        cases = cases + 1;
        $display("CASE %0d: %s", cases, case_name);
    endtask

    function automatic integer next_operand;
        random_state = random_state ^ (random_state << 13);
        random_state = random_state ^ (random_state >> 17);
        random_state = random_state ^ (random_state << 5);
        next_operand = $signed(random_state[7:0]);
    endfunction

    task automatic step
        (input logic reset_value,
         input logic clear_value,
         input logic valid_value,
         input logic last_value,
         input integer a_value,
         input integer b_value);
        if(a_value < -128 || a_value > 127 || b_value < -128 || b_value > 127)begin
            $fatal(1, "TB operand outside signed 8-bit range");
        end

        @(negedge clk);
        rst_n = reset_value;
        clear = clear_value;
        in_valid = valid_value;
        in_last = last_value;
        a = a_value;
        b = b_value;

        expected_valid = 1'b0;
        if(!reset_value || clear_value)begin
            reference_sum = 0;
            expected_result = 32'sd0;
        end else if(valid_value)begin
            reference_sum = reference_sum + a_value * b_value;
            if(last_value)begin
                expected_result = reference_sum[31:0];
                expected_valid = 1'b1;
            end
        end

        @(posedge clk);
        #1;
        checks = checks + 1;
        if(result_valid !== expected_valid)begin
            $fatal(1, "FAIL [%s] check=%0d result_valid expected=%b actual=%b", case_name, checks,
                   expected_valid, result_valid);
        end
        if(result !== expected_result)begin
            $fatal(
                1,
                "FAIL [%s] check=%0d a=%0d b=%0d result expected=%0d actual=%0d expected_hex=%08h actual_hex=%08h",
                case_name, checks, a_value, b_value, expected_result, result, expected_result, result);
        end
    endtask

    initial begin
        begin_case("reset overrides valid and last");
        step(0, 0, 1, 1, -128, -128);
        step(0, 1, 1, 1, 127, 127);
        step(1, 0, 0, 0, 0, 0);

        begin_case("single positive product");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 1, 2, 3);
        step(1, 0, 0, 0, 0, 0);

        begin_case("mixed signs include the last product");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 0, 2, 3);
        step(1, 0, 1, 0, -1, 4);
        step(1, 0, 1, 1, 5, -2);
        step(1, 0, 0, 0, 0, 0);

        begin_case("negative product sign extension");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 1, -1, 1);
        step(1, 0, 0, 0, 127, 127);

        begin_case("signed operand extrema");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 1, -128, -128);
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 1, -128, 127);
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 1, 127, -128);
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 1, 127, 127);

        begin_case("zero product and cancellation");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 0, -128, 0);
        step(1, 0, 1, 0, 127, 127);
        step(1, 0, 1, 1, -127, 127);

        begin_case("invalid last is ignored, idle gaps preserve accumulation");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 0, 3, 7);
        step(1, 0, 0, 1, 127, 127);
        step(1, 0, 0, 0, -128, -128);
        step(1, 0, 1, 1, -2, 4);
        step(1, 0, 0, 1, 9, 9);
        step(1, 0, 0, 0, 9, 9);

        begin_case("clear overrides valid and last, no stale product");
        step(1, 0, 1, 0, 100, 100);
        step(1, 1, 1, 1, -128, -128);
        step(1, 0, 1, 1, 4, -5);

        begin_case("reset during accumulation");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 0, 127, 127);
        step(0, 0, 1, 1, -128, -128);
        step(1, 0, 1, 1, -3, 7);

        begin_case("last does not require an idle cycle afterwards");
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 0, 2, 3);
        step(1, 0, 1, 1, 4, 5);
        step(1, 0, 1, 0, 1, 1);
        step(1, 0, 0, 0, 0, 0);
        step(1, 1, 0, 0, 0, 0);
        step(1, 0, 1, 1, -8, 3);

        begin_case("accumulator width exceeds 16 bits");
        step(1, 1, 0, 0, 0, 0);
        for(integer index = 0; index < 512; index = index + 1)begin
            step(1, 0, 1, index == 511, -128, -128);
        end
        step(1, 0, 0, 0, 0, 0);

        begin_case("negative wide accumulation");
        step(1, 1, 0, 0, 0, 0);
        for(integer index = 0; index < 512; index = index + 1)begin
            step(1, 0, 1, index == 511, -128, 127);
        end
        step(1, 0, 0, 0, 0, 0);

        begin_case("all 256 signed operand values");
        for(integer value = -128; value <= 127; value = value + 1)begin
            step(1, 1, 0, 0, 0, 0);
            step(1, 0, 1, 1, value, -1);
            step(1, 1, 0, 0, 0, 0);
            step(1, 0, 1, 1, -128, value);
        end

        begin_case("deterministic mixed dot products with idle gaps");
        for(integer group_index = 0; group_index < 64; group_index = group_index + 1)begin
            group_length = group_index % 32 + 1;
            step(1, 1, 0, 0, 0, 0);
            for(integer term = 0; term < group_length; term = term + 1)begin
                random_a = next_operand();
                random_b = next_operand();
                if(term % 3 == 1)begin
                    step(1, 0, 0, 1, random_b, random_a);
                end
                step(1, 0, 1, term == group_length - 1, random_a, random_b);
            end
            step(1, 0, 0, 0, 0, 0);
        end

        $display("ALL NPU MAC TESTS PASSED: cases=%0d checks=%0d", cases, checks);
        $finish;
    end

    initial begin
        #1_000_000;
        $fatal(1, "NPU MAC test timed out");
    end
endmodule
